from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,subprocess
root=Path.cwd();task=Path("reports/T0008");out=task/"review-r1-freeze"
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
base=json.loads((task/"planning-baseline.json").read_text())
head=subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()
assert head==base["head"]
new={"src/kmesh/logic/derivations.py","tests/test_derivations.py"}
for p,h in base["source_sha256"].items():
    if p not in new:assert sha(p)==h,p
inputs=["src/kmesh/logic/derivations.py","tests/test_derivations.py","docs/handoffs/T0008-ground-derivations.md","README.md","docs/implementation_status.md","reports/T0008/pi-r1-full/provenance.md","reports/T0008/pi-r1-scripts/check_docs.py"]
ih={}
for p in inputs:
    dest=out/"input-snapshot"/p;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(Path(p).read_bytes());ih[p]=sha(p)
history={str(p):sha(p) for p in task.rglob("*") if p.is_file() and not any(x in p.parts for x in ("pytest-tmp","__pycache__")) and not str(p).startswith(str(out))}
runs=[]
for p in sorted(task.glob("pi-*/**/record.json")):
    r=json.loads(p.read_text())
    integrity={}
    for stream in ("stdout","stderr"):
        stream_path=p.parent/(stream+".txt")
        integrity[stream]=(sha(stream_path)==r.get(stream+"_sha256"))
    runs.append({"path":str(p.parent),"started_at":r.get("started_at_utc"),"argv":r.get("argv"),"exit_code":r.get("exit_code"),"integrity":integrity,"sources_stable":r.get("before",{}).get("source_sha256")==r.get("after",{}).get("source_sha256"),"product_before":r.get("before",{}).get("source_sha256",{}).get("src/kmesh/logic/derivations.py"),"tests_before":r.get("before",{}).get("source_sha256",{}).get("tests/test_derivations.py"),"tail":(p.parent/"stdout.txt").read_text()[-180:],"stderr":(p.parent/"stderr.txt").read_text()[:220]})
audit={"created_at":datetime.now(timezone.utc).isoformat(),"head":head,"input_sha256":ih,"history_sha256":history,"runs":runs}
(out/"audit.json").write_text(json.dumps(audit,ensure_ascii=False,indent=2)+"\n")
print("Input SHA256",json.dumps(ih,indent=2))
for r in sorted(runs,key=lambda r:r["started_at"] or ""): print(json.dumps(r,ensure_ascii=False))
